import openpyxl
from openpyxl.utils import get_column_letter

path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Task']

def dump_block(r1,r2,c1,c2,title,limit_rows=None):
    print(f'\n=== {title} ===')
    for r in range(r1,r2+1):
        for c in range(c1,c2+1):
            addr=f'{get_column_letter(c)}{r}'
            v=ws.cell(r,c).value
            if isinstance(v,str) and v.startswith('='):
                print(f'{addr}: {v}')
            else:
                print(f'{addr}: {v!r}')

# Spot check the formula areas

dump_block(12,17,8,12,'Lookup block 1 H12:L17')
dump_block(19,24,8,12,'Lookup block 2 H19:L24')
dump_block(26,31,8,12,'Lookup block 3 H26:L31')
dump_block(35,40,8,12,'Net SLA buffer H35:L40')
dump_block(42,47,8,12,'Statistics H42:L47')
dump_block(50,50,8,12,'Weighted mean H50:L50')

# Validate no literal errors in expected formula cells
error_literals={'#NAME?','#REF?'}
issues=[]
areas=[
    (12,17,8,12),
    (19,24,8,12),
    (26,31,8,12),
    (35,40,8,12),
    (42,47,8,12),
    (50,50,8,12),
]
for (r1,r2,c1,c2) in areas:
    for r in range(r1,r2+1):
        for c in range(c1,c2+1):
            v=ws.cell(r,c).value
            addr=f'{get_column_letter(c)}{r}'
            if v is None or v=='':
                issues.append((addr,'EMPTY'))
            if isinstance(v,str):
                if v in error_literals:
                    issues.append((addr,v))
                # also guard wrong percentile function
                if 'PERCENTILE.INC' in v or 'PERCENTILE.EXC' in v:
                    issues.append((addr,'BAD_PERCENTILE_FN'))

print('\n=== Validation issues ===')
if issues:
    for addr,problem in issues[:50]:
        print(addr,problem)
    print('Total issues:',len(issues))
else:
    print('None')

